import fs from "fs";
import path from "path";
import { verifyRequest } from "@/lib/auth-helpers";
import { errorResponse } from "@/app/api/_lib/errors";
import { isNonEmptyString } from "@/app/api/_lib/validate";

type Params = { params: Promise<{ mapId: string }> };

export interface RecommendationItem {
  item: string;
  name: string;
  score: number;
  topRule: string;
  hasGlobal: boolean;
  hasLocal: boolean;
}

/**
 * GET /api/recommendations/[mapId]
 * Serves ranked recommendations generated by the MANN deep learning model.
 */
export async function GET(request: Request, { params }: Params) {
  const decoded = await verifyRequest(request);
  if (!decoded) {
    return errorResponse(401, "UNAUTHENTICATED", "Invalid or missing token");
  }

  const { mapId } = await params;
  if (!isNonEmptyString(mapId)) {
    return errorResponse(400, "INVALID_INPUT", "Invalid mapId");
  }

  try {
    // BACKEND: replace static suggestions.json read with a direct call to the
    // Python recommendation microservice (e.g. POST /predict with user graph).
    const suggestionsPath = path.join(
      process.cwd(),
      "recommendation",
      "suggestions.json",
    );

    if (!fs.existsSync(suggestionsPath)) {
      return Response.json({ mapId, suggestions: [] });
    }

    const fileContent = fs.readFileSync(suggestionsPath, "utf-8");
    const allSuggestions: Record<string, RecommendationItem[]> = JSON.parse(fileContent);

    // Look for matching user suggestions; fall back to available cluster
    const uid = decoded.uid;
    const userSuggestions =
      allSuggestions[uid] ||
      allSuggestions["u_alice"] ||
      Object.values(allSuggestions)[0] ||
      [];

    return Response.json({
      mapId,
      suggestions: userSuggestions.slice(0, 5),
    });
  } catch (err) {
    console.error("GET /api/recommendations/[mapId] error:", err);
    return errorResponse(500, "INTERNAL_ERROR", "Failed to fetch recommendations");
  }
}
